#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    int m=3*n;
	    vector<long long >a(m);
	    for(int i=0;i<m;i++){
	        cin>>a[i];
	    }
	    sort(a.rbegin(),a.rend());
	    long long yxz=0;
	    vector<long long>pref(m+1,0);
	    for(int i=0;i<m;i++){
	        pref[i+1]=pref[i]+a[i];
	    }
	    long long ans=0;
	    for(int i=0;i<=n;i++){
	        auto value =[&](int b){
	            int mid=i+2*b;
	            int last=m-2*i-b;
	            return 2LL*pref[i]+pref[mid]+3LL*pref[last];
	        };
	        int lo=0;
	        int hi=n-i;
	        while(lo<hi){
	            int b=(lo+hi+1)/2;
	            int oldb=b-1;
	            int p1=i+2*oldb;
	            int p2=m-2*i-oldb;
	            long long change=a[p1]+a[p1+1]-3LL*a[p2-1];
	            if(change>=0){
	                lo=b;
	                
	            }else{
	                hi=b-1;
	            }
	        }
	            yxz=value(lo);
	            ans=max(ans,yxz);
	        }
	        cout<<ans<<endl;
	    }
	
	

}
